import{_ as s}from"./chunks/gm2l1_dn2nz_concept.B9TmuEbb.js";import{_ as n,o as t,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/gm2l1_dn2nz_continuous.DkDz90N8.png",d="/ascendc.github.io/assets/gm2l1_dn2nz.BXSTebcC.png",e="/ascendc.github.io/assets/gm2l1_dn2nz_smallc0.CORRr1pe.png",i="/ascendc.github.io/assets/datacopy_gm2l1_dn2nz_demo.-kuekB7P.png",S=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"DataCopy（GMToL1随路转换-DN2NZ搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_DN2NZ"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_DN2NZ.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_DN2NZ.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),r={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_DN2NZ.md"};function o(N,a,_,h,u,m){return t(),p("div",null,[...a[0]||(a[0]=[l('<div><article class="markdown-body"><h1>DataCopy（GMToL1随路转换-DN2NZ搬运）<a id="ZH-CN_TOPIC_0000002563847574"></a></h1><h2 id="产品支持情况">产品支持情况<a id="section1550532418810"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="section474617392321"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>随路格式转换数据搬运，适用于在搬运时进行DN到NZ格式的转换。数据从Global Memory搬运至L1 Buffer（TPosition为A1/B1），搬运过程中完成DN-&gt;NZ格式转换。</p><p>DN到NZ的格式转换等价于ND到ZN的格式转换，如下图所示：</p><p><strong>图1</strong> DN到NZ格式转换示意图</p><p><img src="'+s+`" alt title="DN到NZ格式转换示意图"></p><h2 id="函数原型">函数原型<a id="section1954364615315"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">enableSmallC0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Dn2NzParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">);</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数或者目的操作数的数据类型。</td></tr><tr><td>enableSmallC0</td><td>SmallC0模式开关：当dValue小于等于4的时候，C0_SIZE会补齐到4 * sizeof(T)字节，默认不开启。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor，存储位置为L1 Buffer（TPosition为A1/B1）。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为GlobalTensor。<br><a href="../../data_structures/GlobalTensor/SetL2CacheHint.html">SetL2CacheHint</a>支持的L2 Cache控制模式如下：CacheMode::CACHE_MODE_DISABLE、CacheMode::CACHE_MODE_NORMAL。</td></tr><tr><td>intriParams</td><td>输入</td><td>搬运参数，Dn2NzParams类型，具体参数说明请参考<a href="#table9182515919">表3</a>。</td></tr></tbody></table><p><strong>表3</strong> Dn2NzParams结构体参数定义<a id="table9182515919"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>dnNum</td><td>传输DN矩阵的数目，取值范围：dnNum∈[0, 4095]。<br><strong>注：dnNum=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>nValue</td><td>DN矩阵的列数，取值范围：nValue∈[0, 16384]。<br><strong>注：nValue=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>dValue</td><td>DN矩阵的行数，取值范围：dValue∈[0, 2^21-1]。<br><strong>注：dValue=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>srcDnMatrixStride</td><td>源操作数相邻DN矩阵起始地址间的偏移，取值范围：srcDnMatrixStride∈[0, 2^40-1]，单位为元素。<br>  • dnNum = 1时，srcDnMatrixStride无意义，设置为0即可。<br>  • dnNum ≠ 1时，当srcDnMatrixStride = 0时，表示源矩阵中搬入的每个DN矩阵都从第一个DN矩阵读取。</td></tr><tr><td>srcDValue</td><td>源操作数同一DN矩阵的相邻行起始地址间的偏移，取值范围：srcDValue∈[1, 2^40-1]，单位为元素。</td></tr><tr><td>dstNzC0Stride</td><td>DN转换到NZ格式后，源操作数中的一列会转换为目的操作数的多行。dstNzC0Stride表示，目的NZ矩阵中，来自源操作数同一列的多行数据相邻行起始地址间的偏移，取值范围：dstNzC0Stride∈[1, 16384]，单位：C0_SIZE（32字节）。</td></tr><tr><td>dstNzNStride</td><td>目的NZ矩阵中，Z型矩阵相邻行起始地址之间的偏移。取值范围：dstNzNStride∈[1, 16384]，单位：C0_SIZE（32字节）。</td></tr><tr><td>dstNzMatrixStride</td><td>目的NZ矩阵中，相邻NZ矩阵起始地址的偏移，取值范围：dstNzMatrixStride∈[0, 16384]，单位为元素个数。<br>  • dnNum = 1时，dstNzMatrixStride无意义，设置为0即可。<br>  • dnNum ≠ 1时，当dstNzMatrixStride = 0时，表示目的矩阵中搬入的每个NZ矩阵都会覆盖第一个NZ矩阵。</td></tr></tbody></table><p><strong>连续搬运</strong></p><p>以half数据类型为例，下图为DN2NZ连续搬运示意图。Dn2NzParams结构体参数配置说明如下：</p><ul><li>dnNum = 1，表示搬运的DN矩阵的数量为1。</li><li>nValue = 16，一个DN矩阵的列数。</li><li>dValue = 23，一个DN矩阵的行数。当dValue * sizeof(T)不满足32字节对齐时，在目的矩阵中会补0对齐到32字节。</li><li>srcDnMatrixStride = 0，只有一个DN矩阵，该值为0。</li><li>srcDValue = 16，表示源矩阵一行的所含元素个数，即16个half数据类型的元素。</li><li>dstNzC0Stride = 16，NZ矩阵中相邻Z矩阵起始地址的偏移，偏移为16个C0_SIZE，也就是16 * 32字节。</li><li>dstNzNStride = 1，表示NZ矩阵中相邻行起始地址的偏移。</li><li>dstNzMatrixStride = 0，输入只有一个DN矩阵，该值为0。</li></ul><p><strong>图2</strong> DN2NZ转换示意图（连续搬运）</p><p><img src="`+c+'" alt title="DN2NZ转换示意图（连续搬运）"></p><p><strong>非连续搬运</strong></p><p>以half数据类型为例，下图为DN2NZ非连续搬运示意图。Dn2NzParams结构体参数配置说明如下：</p><ul><li>dnNum = 2，表示搬运的DN矩阵的数量为2。</li><li>nValue = 8，一个DN矩阵的列数。</li><li>dValue = 23，一个DN矩阵的行数。当dValue * sizeof(T)不满足32字节对齐时，在目的矩阵中会补0对齐到32字节。</li><li>srcDnMatrixStride = 400，表示相邻DN矩阵起始地址的偏移，每行16个元素，共25行，偏移为16 * 25= 400个元素。</li><li>srcDValue = 16，表示源矩阵一行的所含元素个数，即16个half数据类型的元素。</li><li>dstNzC0Stride = 37，NZ矩阵中相邻Z矩阵起始地址的偏移，偏移为37个C0_SIZE。</li><li>dstNzNStride = 2，表示NZ矩阵中相邻行起始地址的偏移。</li><li>dstNzMatrixStride = 320，相邻NZ矩阵起始地址的偏移，每行16个元素，共20行，偏移为16 * 20 = 320个元素。</li></ul><p><strong>图3</strong> DN2NZ转换示意图（非连续搬运）</p><p><img src="'+d+'" alt title="DN2NZ转换示意图（非连续搬运）"></p><p><strong>SmallC0模式</strong></p><p>当dValue小于等于4的时候，可以使能SmallC0模式，C0_SIZE会对齐到4 * sizeof(T)字节，当dValue * sizeof(T)不满足4 * sizeof(T)对齐时，在目的矩阵中会补0对齐到4 * sizeof(T)。</p><p>若整个目的矩阵没有C0_SIZE（32字节）对齐，则目的矩阵中尾部补0直到32字节对齐。在该模式下，dstNzNStride参数和dstNzC0Stride参数，无需配置。</p><p><strong>图4</strong> DN2NZ转换示意图（SmallC0模式）</p><p><img src="'+e+'" alt title="DN2NZ转换示意图（SmallC0模式）"></p><h2 id="数据类型">数据类型<a id="section4219135304818"></a><a class="header-anchor" href="#数据类型">​</a></h2><p>支持的数据类型为：int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>当输入数据类型是b4时，DN2NZ过程中数据是基于b8类型进行处理，因此参数需要根据b8类型进行设置，nValue必须是2的倍数。</li><li>位于Global Memory的源地址必须1字节对齐，位于L1 Buffer的目的地址必须32字节对齐。</li><li>当Dn2NzParams结构体参数dnNum、nValue、dValue任意一个值为0时，该指令不会执行，该接口将被视为NOP（空操作）。</li><li>搬运至L1 Buffer的数据不能重叠，如果存在重叠写入，硬件不会产生任何警告或错误，并且不保证重叠数据的写入顺序。</li><li>Dn2NzParams结构体参数的值需在取值范围内，参数取值范围如<a href="#table_dn2nz_range">表4</a>所示。</li></ul><p><strong>表 4</strong> Dn2NzParams结构体参数取值范围<a id="table_dn2nz_range"></a></p><table><thead><tr><th>参数名称</th><th>取值范围</th></tr></thead><tbody><tr><td>dnNum</td><td>[0, 4095]</td></tr><tr><td>nValue</td><td>[0, 16384]</td></tr><tr><td>dValue</td><td>[0, 2^21-1]</td></tr><tr><td>srcDnMatrixStride</td><td>[0, 2^40-1]</td></tr><tr><td>srcDValue</td><td>[1, 2^40-1]</td></tr><tr><td>dstNzC0Stride</td><td>[1, 16384]</td></tr><tr><td>dstNzNStride</td><td>[1, 16384]</td></tr><tr><td>dstNzMatrixStride</td><td>[0, 16384]</td></tr></tbody></table><h2 id="调用示例">调用示例<a id="section122101199486"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>如下示例中：在A矩阵转置，数据类型为half的场景下，使用DataCopy进行随路DN2NZ数据搬运。</p><p>搬运过程的数据排布变化示意图如下：</p><p><img src="'+i+`" alt></p><p>示例代码片段如下，完整示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/00_data_movement/data_copy_gm2l1">data_copy_gm2l1样例</a>中场景3。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// m=40,k=56,fractalShape[0] = 16,fractalShape[1] = 16,fractalSize = 16 * fractalShape[1] </span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Dn2NzParams</span><span class="w"> </span><span class="n">dn2nzA1Params</span><span class="p">;</span><span class="w"> </span>
<span class="c1">// 传输DN矩阵的数目 </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">dnNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w"> </span>
<span class="c1">// DN矩阵的列数 </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">nValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">40</span><span class="p">;</span><span class="w"> </span>
<span class="c1">// DN矩阵的行数 </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">dValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">56</span><span class="p">;</span><span class="w"> </span>
<span class="c1">// 只传输了1个DN矩阵，该参数无效 </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">srcDnMatrixStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span>
<span class="c1">// 源操作数中同一DN矩阵行起始地址间的偏移 </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">srcDValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">40</span><span class="p">;</span><span class="w"> </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">dstNzC0Stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span><span class="w"> </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">dstNzNStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w"> </span>
<span class="n">dn2nzA1Params</span><span class="p">.</span><span class="n">dstNzMatrixStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">a1Local</span><span class="p">,</span><span class="w"> </span><span class="n">aGM</span><span class="p">,</span><span class="w"> </span><span class="n">dn2nzA1Params</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const g=n(r,[["render",o]]);export{S as __pageData,g as default};
